    }
  },
  "layers": [
    {
      "id": "water",
      "type": "fill",
      "source": "mytiles",
      "source-layer": "water",          // name inside the PMTiles file
      "paint": { "fill-color": "#a0c8f0" }
    },
    {
      "id": "roads",
      "type": "line",
      "source": "mytiles",
      "source-layer": "road",
      "paint": { "line-color": "#777", "line-width": 1 }
    }
  ]
}
```

### Raster example (satellite imagery)

```json
{
  "version": 8,
  "sources": {
    "sat": {
      "type": "raster",
      "url": "pmtiles://https://username.github.io/your-project/sat.pmtiles",
      "tileSize": 256
    }
  },
  "layers": [
    {
      "id": "sat",
