      "source": "sat"
    }
  ]
}
```

### Terrain (raster‑dem) example

```json
{
  "version": 8,
  "sources": {
    "elev": {
      "type": "raster-dem",
      "url": "pmtiles://https://username.github.io/your-project/elev.pmtiles",
      "encoding": "terrarium"
    }
  },
  "terrain": {
    "source": "elev",
    "exaggeration": 1.5
  }
}
```

> **Important:** Use **`url:`** (not `tiles:`). The PMTiles protocol reads the archive header, injects a TileJSON with the correct `minzoom`/`maxzoom`, and MapLibre will automatically over‑zoom beyond the max‑zoom that exists in the file.

